{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Ketoprofen, a lipophilic acidic drug with an aromatic ketone and carboxylic acid, has an absolute oral bioavailability of at least 92% in humans, supporting high F for the similarly acidic, lipophilic warfarin scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Suprofen, a close ketoprofen analogue, shows 92.2% absolute oral bioavailability with no significant first-pass effect, indicating that this aryl-acid class is well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Terodiline, a lipophilic drug with two phenyl groups and an amine, has a mean absolute oral bioavailability of 92%, supporting high F for the lipophilic phenyl-substituted query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Diphenhydramine, a lipophilic benzhydryl ether, has an absolute oral bioavailability of 72% at a pharmacological dose, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C70"],
      "claim": "Vorinostat, a polar hydroxamic acid with an anilide, still achieves 43% absolute oral bioavailability, showing that even polar molecules with high transfer scores are high at this threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C57"],
      "claim": "Ampicillin, a zwitterionic beta-lactam with limited permeability, has an absolute oral bioavailability of about 40%, still above 20%; the more lipophilic query should be at least as bioavailable.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is warfarin, a 4-hydroxycoumarin anticoagulant. Multiple high-transfer analogues with direct human absolute oral bioavailability measurements show F values well above 20% (ketoprofen ≥92%, suprofen 92.2%, terodiline 92%, diphenhydramine 72%, vorinostat 43%, ampicillin 40%). These support high oral bioavailability. No affirmative threshold-relevant evidence supports F < 20% for this scaffold.",
  "evidence_gaps": [
    "No direct warfarin bioavailability record is present in the supplied evidence; the prediction relies on high-transfer analogues.",
    "Some analogues such as labetalol show variable or low F, but their extensive first-pass metabolism is not representative of warfarin's metabolic profile."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

